RESOURCES_BY_SKILL: dict[str, list[dict]] = {}
for r in RESOURCES:
    for s in r["skills"]:
        RESOURCES_BY_SKILL.setdefault(s, []).append(r)

FORMATS = sorted({r["format"] for r in RESOURCES})
DIFFICULTIES = ["Beginner", "Intermediate", "Advanced"]
ALL_SKILLS = sorted(RESOURCES_BY_SKILL.keys())


def resources_for_skill(skill: str, limit: int = 3, preferred_format: str | None = None) -> list[dict]:
    """Return verified resources relevant to a skill, preferring the learner's format."""
    pool = list(RESOURCES_BY_SKILL.get(skill, []))
    if not pool:
        low = skill.lower()
        pool = [r for r in RESOURCES if any(low in s.lower() or s.lower() in low for s in r["skills"])]
    if preferred_format and preferred_format != "A mix of everything":
        pool.sort(key=lambda r: 0 if r["format"] == preferred_format else 1)
    return pool[:limit]
